// Target reporting date is yesterday (completed 24h cycle for finalized Meta metrics)
const yesterday = $now.minus({ days: 1 });
const targetDateStr = yesterday.toFormat('yyyy-MM-dd');

// Unix timestamps for Meta Graph API since/until parameters
const sinceTimestamp = Math.floor(yesterday.startOf('day').toSeconds());
const untilTimestamp = Math.floor(yesterday.endOf('day').toSeconds());

// Meta Credentials & Account IDs from environment or configured defaults
const metaAccessToken = $env.META_ACCESS_TOKEN || 'EAAG_DENTALPIN_META_ACCESS_TOKEN';
const igUserId = $env.META_IG_USER_ID || '17841400000000000';
const fbPageId = $env.META_FB_PAGE_ID || '100000000000000';

// DentalPin Backend Configuration
const dentalpinApiBase = ($env.DENTALPIN_API_BASE_URL || 'https://dental-api-2z19.onrender.com').replace(/\/+$/, '');
const dentalpinSyncPath = $env.DENTALPIN_SYNC_PATH || '/api/v1/social_automation/insights';
const dentalpinSyncUrl = `${dentalpinApiBase}${dentalpinSyncPath}`;
const dentalpinApiKey = $env.DENTALPIN_API_KEY || '';

return [
  {
    json: {
      target_date: targetDateStr,
      since: sinceTimestamp,
      until: untilTimestamp,
      meta_access_token: metaAccessToken,
      ig_user_id: igUserId,
      fb_page_id: fbPageId,
      ig_account_id: 'dr_mokhtar_dental',
      fb_account_id: 'dr_mokhtar_cabinet',
      dentalpin_api_base: dentalpinApiBase,
      dentalpin_sync_url: dentalpinSyncUrl,
      dentalpin_api_key: dentalpinApiKey
    }
  }
];

const config = $('Init Config & Calculate Dates').first().json;

// Safely retrieve items from each upstream node
let igInfo = {};
let igInsights = [];
let fbInfo = {};
let fbInsights = [];

try {
  const igInfoItem = $('Fetch Instagram Profile').first()?.json || {};
  if (!igInfoItem.error) igInfo = igInfoItem;
} catch (e) {}

try {
  const igInsightsItem = $('Fetch Instagram Insights').first()?.json || {};
  if (Array.isArray(igInsightsItem.data)) igInsights = igInsightsItem.data;
} catch (e) {}

try {
  const fbInfoItem = $('Fetch Facebook Page Info').first()?.json || {};
  if (!fbInfoItem.error) fbInfo = fbInfoItem;
} catch (e) {}

try {
  const fbInsightsItem = $('Fetch Facebook Page Insights').first()?.json || {};
  if (Array.isArray(fbInsightsItem.data)) fbInsights = fbInsightsItem.data;
} catch (e) {}

// Helper to extract numeric metric value safely
function extractMetric(dataArray, metricName) {
  if (!Array.isArray(dataArray)) return 0;
  const item = dataArray.find(m => m && m.name === metricName);
  if (!item || !Array.isArray(item.values) || item.values.length === 0) return 0;

  const val = item.values[item.values.length - 1]?.value;
  return typeof val === 'number' ? val : (parseInt(val, 10) || 0);
}

// 1. Build Instagram Record
const igFollowers = typeof igInfo.followers_count === 'number' ? igInfo.followers_count : 0;
const igReach = extractMetric(igInsights, 'reach');
const igViews = extractMetric(igInsights, 'profile_views');
const igClicks = extractMetric(igInsights, 'website_clicks');

const instagramRecord = {
  platform: 'instagram',
  account_id: igInfo.username || config.ig_account_id,
  date: config.target_date,
  total_followers: igFollowers,
  reach: igReach,
  profile_views: igViews,
  website_clicks: igClicks,
  saves: 0
};

// 2. Build Facebook Record
const fbFollowers = typeof fbInfo.followers_count === 'number'
  ? fbInfo.followers_count
  : (typeof fbInfo.fan_count === 'number' ? fbInfo.fan_count : 0);
const fbReach = extractMetric(fbInsights, 'page_impressions_unique');
const fbViews = extractMetric(fbInsights, 'page_views_total');
const fbClicks = extractMetric(fbInsights, 'page_total_actions');

const facebookRecord = {
  platform: 'facebook',
  account_id: fbInfo.name ? fbInfo.name.toLowerCase().replace(/[^a-z0-9_]/g, '_') : config.fb_account_id,
  date: config.target_date,
  total_followers: fbFollowers,
  reach: fbReach,
  profile_views: fbViews,
  website_clicks: fbClicks,
  saves: 0
};

const syncPayload = {
  insights: [instagramRecord, facebookRecord]
};

return [
  {
    json: {
      sync_payload: syncPayload,
      target_date: config.target_date,
      dentalpin_api_base: config.dentalpin_api_base,
      dentalpin_sync_url: config.dentalpin_sync_url,
      dentalpin_api_key: config.dentalpin_api_key,
      summary: {
        date: config.target_date,
        instagram: { followers: igFollowers, reach: igReach, views: igViews, clicks: igClicks },
        facebook: { followers: fbFollowers, reach: fbReach, views: fbViews, clicks: fbClicks }
      }
    }
  }
];

const prev = $('Normalize & Build Unified Insights').first().json;
const syncResult = $json;

return [
  {
    json: {
      success: true,
      execution_timestamp: $now.toISO(),
      target_date: prev.target_date,
      summary: prev.summary,
      backend_response: syncResult,
      message: `DentalPin social media insights successfully synchronized for date: ${prev.target_date}`
    }
  }
];
